public partial class SpecialDelete_Redirect : System.Web.UI.Page
{
    protected void Page_Load(object sender, EventArgs e)
    {
        if (Request["accspecialdeletekey"] != null && !string.IsNullOrEmpty(Request["accspecialdeletekey"]))
        {
            var userName = Cryptography.CfsEnCrypt(AppSession.AccUserName.ToString());
            var onuserId = Cryptography.CfsEnCrypt(AppSession.OnAccId.ToString());

            var accUrlIndentify = Request["accspecialdeletekey"];
            var mappingUrlSection = MappingSpecialDeleteUrlSection.Instance.SpecialDeleteUrl;
            if (mappingUrlSection != null)
            {
                var getMappingConfig = (from m in
                                            mappingUrlSection.Cast<SpecialDeleteUrlElement>().Where(
                                                m => m.AccUrl.ToLower().Equals(accUrlIndentify.ToLower()) && m.Active)
                                        select m);
                if (getMappingConfig != null && getMappingConfig.Count() > 0)
                {
                    var napUrl = getMappingConfig.First().NapUrl;
                    var url = string.Format("{0}?username={1}&onuserid={2}&redirectUrl={3}", NapURL(), userName, onuserId, napUrl);
                    Response.Redirect(url);
                }
            }
        }
        else
        {
            Response.Redirect("Index.aspx");
        }
    }
	
	private string NapURL()
    {
        Uri uri = HttpContext.Current.Request.Url;
        //var publisIPs = ConfigurationManager.AppSettings["PublicIPs"].ToString().Split(new char[]{','},StringSplitOptions.RemoveEmptyEntries);
        ////string host = uri.Scheme + Uri.SchemeDelimiter + uri.Host + (uri.Port == 80 ? "" : ":" + uri.Port);
        //bool isUsedIP = false;

        //foreach (var Ip in publisIPs)
        //{ 
        //    if (host.Contains(Ip.ToString()))
        //    {
        //        isUsedIP=true;
        //        break;
        //    }
        //}

        //return isUsedIP ? string.Format(ConfigurationManager.AppSettings["NapReportSSOUrl"],host) : ConfigurationManager.AppSettings["NapReportLoginUrl"];
        return string.Format(ConfigurationManager.AppSettings["NapSpecialDeleteLoginUrl"], uri.Scheme + Uri.SchemeDelimiter + HttpContext.Current.Request.Headers["Host"].ToString());
    }
}